		s.doer = &http.Client{Timeout: 10 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	}
	if s.resolver == nil {
		s.resolver = net.DefaultResolver
	}
	return s
}

// EventTypes are the events Tally sends. An endpoint subscribes to some of them, or to "*" for all.
var EventTypes = []string{
	"customer.created", "customer.updated", "customer.deleted",
	"subscription.created", "subscription.updated", "subscription.canceled",
	"invoice.created", "invoice.paid", "invoice.payment_failed", "invoice.voided",
}

// Errors.
var (
	ErrInvalidURL    = errors.New("invalid webhook URL")
	ErrInvalidEvents = errors.New("invalid event types")
)

// CheckURL checks a webhook URL before it is saved: an absolute http or https URL whose host resolves.
func (s *Service) CheckURL(ctx context.Context, raw string) error {
	u, err := url.Parse(raw)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
		return fmt.Errorf("%w: use an absolute http or https URL", ErrInvalidURL)
	}
	host := u.Hostname()
	if net.ParseIP(host) != nil {
		return nil
	}
	addrs, err := s.resolver.LookupIPAddr(ctx, host)
	if err != nil || len(addrs) == 0 {
		return fmt.Errorf("%w: the host %q does not resolve", ErrInvalidURL, host)
	}
	return nil
}

// CheckEvents checks an endpoint's event types.
func CheckEvents(types []string) error {
	if len(types) == 0 {
		return fmt.Errorf("%w: name at least one event type, or \"*\"", ErrInvalidEvents)
	}
	for _, t := range types {
		if t != "*" && !slices.Contains(EventTypes, t) {
			return fmt.Errorf("%w: unknown event type %q", ErrInvalidEvents, t)
		}
	}
	return nil
}

// NewSecret returns a new signing secret for an endpoint.
func NewSecret() string { return store.NewToken("whsec_") }

// Sign returns the signature of a delivery's body: the hex HMAC-SHA256 of the body, keyed with the endpoint's secret.
func Sign(secret string, body []byte) string {
	m := hmac.New(sha256.New, []byte(secret))
	m.Write(body)
	return hex.EncodeToString(m.Sum(nil))
}

// Publish records an event and queues a delivery of it to every enabled endpoint of the organization that subscribes to its
// type. The deliveries are sent by RunDue.
func (s *Service) Publish(ctx context.Context, orgID, eventType string, data any) error {
	raw, err := json.Marshal(data)
	if err != nil {
		return err
	}
	now := s.clock.Now()
	e, err := s.store.AddEvent(orgID, eventType, raw, now)
	if err != nil {
		return err
	}
	for _, ep := range s.store.WebhookEndpoints(orgID) {
		if !ep.Enabled || !(slices.Contains(ep.Events, "*") || slices.Contains(ep.Events, eventType)) {
			continue
		}
		next := now
		if _, err := s.store.CreateDelivery(store.Delivery{OrgID: orgID, EndpointID: ep.ID, EventID: e.ID, NextAttemptAt: &next}, now); err != nil {
			return err
		}
	}
	return nil
}

// RunDue attempts every delivery that is due and returns how many it attempted. Each delivery is attempted once: an answer
// with a 2xx status marks it succeeded, anything else failed.
func (s *Service) RunDue(ctx context.Context) (int, error) {
	n := 0
	for _, d := range s.store.DueDeliveries(s.clock.Now()) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		s.deliver(ctx, d)
		n++
	}
	return n, nil
}

// Body is what a delivery POSTs.
type Body struct {
	ID        string          `json:"id"`
	Type      string          `json:"type"`
	CreatedAt time.Time       `json:"created_at"`
	Data      json.RawMessage `json:"data"`
}

func (s *Service) deliver(ctx context.Context, d store.Delivery) {
	status, errText := 0, ""
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	e, eok := s.store.EventByID(d.EventID)
	switch {
	case !ok || !ep.Enabled:
		errText = "the endpoint is disabled or was deleted"
	case !eok:
		errText = "the event no longer exists"
	default:
		status, errText = s.send(ctx, ep, e)
	}
	now := s.clock.Now()
	_, _ = s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
		d.Attempts++
		d.LastAttemptAt = &now
		d.NextAttemptAt = nil
		d.ResponseStatus = status
		d.Error = errText
		if errText == "" {
			d.Status = store.DeliverySucceeded
		} else {
			d.Status = store.DeliveryFailed
		}
		return nil
	})
}

// send POSTs the event to the endpoint and returns the response status and, when it failed, why.
func (s *Service) send(ctx context.Context, ep store.WebhookEndpoint, e store.Event) (int, string) {
	body, err := json.Marshal(Body{ID: e.ID, Type: e.Type, CreatedAt: e.CreatedAt, Data: e.Data})
	if err != nil {
		return 0, err.Error()
	}
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
	if err != nil {
		return 0, err.Error()
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
	req.Header.Set("Tally-Event-Id", e.ID)
	req.Header.Set("Tally-Event-Type", e.Type)
	req.Header.Set("Tally-Signature", Sign(ep.Secret, body))
	resp, err := s.doer.Do(req)
	if err != nil {
		return 0, err.Error()
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return resp.StatusCode, fmt.Sprintf("the endpoint answered %d", resp.StatusCode)
	}
	return resp.StatusCode, ""
}
package webhooks_test

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
	"example.com/tally/internal/webhooks"
)

func TestSign(t *testing.T) {
	// HMAC-SHA256("key", "The quick brown fox jumps over the lazy dog")
	const want = "f7bc83f430538424b13298e6aa6fb143ef4d59a14946175997479dbc2d1a3cd8"
	if got := webhooks.Sign("key", []byte("The quick brown fox jumps over the lazy dog")); got != want {
		t.Fatalf("Sign = %s", got)
	}
}

func TestCheckURL(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	for _, ok := range []string{"https://hooks.acme.example/tally", "https://93.184.216.34:8443/in"} {
		if err := e.Webhooks.CheckURL(ctx, ok); err != nil {
			t.Errorf("CheckURL(%q) = %v", ok, err)
		}
	}
	for _, bad := range []string{"", "hooks.acme.example/x", "ftp://hooks.acme.example/", "https:///x", "https://unknown.example/x"} {
		if err := e.Webhooks.CheckURL(ctx, bad); !errors.Is(err, webhooks.ErrInvalidURL) {
			t.Errorf("CheckURL(%q) = %v, want ErrInvalidURL", bad, err)
		}
	}
	if err := webhooks.CheckEvents([]string{"invoice.paid", "*"}); err != nil {
		t.Error(err)
	}
	for _, bad := range [][]string{nil, {"invoice.eaten"}} {
		if err := webhooks.CheckEvents(bad); !errors.Is(err, webhooks.ErrInvalidEvents) {
			t.Errorf("CheckEvents(%v) = %v", bad, err)
		}
	}
}

func TestPublishAndDeliver(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	now := e.Clock.Now()
	all, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_a", Enabled: true}, now)
	paid, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/paid", Events: []string{"invoice.paid"}, Secret: "whsec_b", Enabled: true}, now)
	_, _ = e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/off", Events: []string{"*"}, Secret: "whsec_c", Enabled: false}, now)
	_, _ = e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Globex.ID, URL: "https://hooks.globex.example/", Events: []string{"*"}, Secret: "whsec_d", Enabled: true}, now)

	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	n, err := e.Webhooks.RunDue(ctx)
	if err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v (only the endpoint for every event wants customer.created)", n, err)
	}
	reqs := e.HTTP.Requests()
	if len(reqs) != 1 || reqs[0].URL != all.URL || reqs[0].Method != http.MethodPost {
		t.Fatalf("requests = %+v", reqs)
	}
	if got, want := reqs[0].Header.Get("Tally-Signature"), webhooks.Sign("whsec_a", reqs[0].Body); got != want {
		t.Fatalf("signature %q, want %q", got, want)
	}
	var body webhooks.Body
	if err := json.Unmarshal(reqs[0].Body, &body); err != nil || body.Type != "customer.created" || reqs[0].Header.Get("Tally-Event-Id") != body.ID {
		t.Fatalf("body = %s (%v)", reqs[0].Body, err)
	}
	ds := e.Store.Deliveries(e.Acme.ID, all.ID)
	if len(ds) != 1 || ds[0].Status != store.DeliverySucceeded || ds[0].Attempts != 1 || ds[0].ResponseStatus != 200 {
		t.Fatalf("deliveries = %+v", ds)
	}

	e.HTTP.Respond = func(r apitest.Request) (int, error) { return http.StatusInternalServerError, nil }
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_1"})
	if n, _ := e.Webhooks.RunDue(ctx); n != 2 {
		t.Fatalf("RunDue = %d, want 2", n)
	}
	for _, ep := range []store.WebhookEndpoint{all, paid} {
		ds := e.Store.Deliveries(e.Acme.ID, ep.ID)
		last := ds[len(ds)-1]
		if last.Status != store.DeliveryFailed || last.ResponseStatus != 500 || last.Error == "" {
			t.Fatalf("delivery to %s = %+v", ep.URL, last)
		}
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a failed delivery was sent again: %d", n)
	}
}
package api

import (
	"errors"
	"net/http"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/store"
	"example.com/tally/internal/webhooks"
)

func (s *Server) hookError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, webhooks.ErrInvalidURL):
		writeError(w, http.StatusUnprocessableEntity, "invalid_url", err.Error())
	case errors.Is(err, webhooks.ErrInvalidEvents):
		writeError(w, http.StatusUnprocessableEntity, "invalid_events", err.Error())
	default:
		s.storeError(w, err)
	}
}

func (s *Server) listEndpoints(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	writeJSON(w, http.StatusOK, list{Items: s.store.WebhookEndpoints(p.OrgID)})
}

// createEndpoint adds an endpoint: {"url": ..., "events": [...]}. The answer includes the signing secret.
func (s *Server) createEndpoint(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		URL    string   `json:"url"`
		Events []string `json:"events"`
	}
	if !decode(w, r, &in) {
		return
	}
	if err := s.hooks.CheckURL(r.Context(), in.URL); err != nil {
		s.hookError(w, err)
		return
	}
	if err := webhooks.CheckEvents(in.Events); err != nil {
		s.hookError(w, err)
		return
	}
	ep, err := s.store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: p.OrgID, URL: in.URL, Events: in.Events, Secret: webhooks.NewSecret(), Enabled: true}, s.clock.Now())
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, ep)
}

func (s *Server) getEndpoint(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	ep, ok := s.store.WebhookEndpoint(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such webhook endpoint")
		return
	}
	writeJSON(w, http.StatusOK, ep)
}

func (s *Server) updateEndpoint(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		URL     *string   `json:"url"`
		Events  *[]string `json:"events"`
		Enabled *bool     `json:"enabled"`
	}
	if !decode(w, r, &in) {
		return
	}
	if in.URL != nil {
		if err := s.hooks.CheckURL(r.Context(), *in.URL); err != nil {
			s.hookError(w, err)
			return
		}
	}
	if in.Events != nil {
		if err := webhooks.CheckEvents(*in.Events); err != nil {
			s.hookError(w, err)
			return
		}
	}
	ep, err := s.store.UpdateWebhookEndpoint(p.OrgID, r.PathValue("id"), func(ep *store.WebhookEndpoint) error {
		if in.URL != nil {
			ep.URL = *in.URL
		}
		if in.Events != nil {
			ep.Events = *in.Events
		}
		if in.Enabled != nil {
			ep.Enabled = *in.Enabled
			if ep.Enabled {
				ep.DisabledReason = ""
			}
		}
		return nil
	})
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, ep)
}

func (s *Server) deleteEndpoint(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	if err := s.store.DeleteWebhookEndpoint(r.PathValue("id")); err != nil {
		s.storeError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (s *Server) listDeliveries(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	ep, ok := s.store.WebhookEndpoint(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such webhook endpoint")
		return
	}
	writeJSON(w, http.StatusOK, list{Items: s.store.Deliveries(p.OrgID, ep.ID)})
}

func eventKey(e store.Event) cursor { return cursor{T: e.CreatedAt, ID: e.ID} }

func (s *Server) listEvents(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	items, next := pageOf(s.store.Events(p.OrgID, r.URL.Query().Get("type")), eventKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

func (s *Server) getEvent(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	e, ok := s.store.Event(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such event")
		return
	}
	writeJSON(w, http.StatusOK, e)
}

