// nonPublic are the address ranges a delivery must never reach: this server's own machine and networks, the cloud metadata
// service and the other link-local, private and shared ranges, and multicast and broadcast.
var nonPublic = []netip.Prefix{
	netip.MustParsePrefix("0.0.0.0/8"),
	netip.MustParsePrefix("10.0.0.0/8"),
	netip.MustParsePrefix("100.64.0.0/10"),
	netip.MustParsePrefix("127.0.0.0/8"),
	netip.MustParsePrefix("169.254.0.0/16"),
	netip.MustParsePrefix("172.16.0.0/12"),
	netip.MustParsePrefix("192.168.0.0/16"),
	netip.MustParsePrefix("224.0.0.0/4"),
	netip.MustParsePrefix("255.255.255.255/32"),
	netip.MustParsePrefix("::/128"),
	netip.MustParsePrefix("::1/128"),
	netip.MustParsePrefix("fc00::/7"),
	netip.MustParsePrefix("fe80::/10"),
	netip.MustParsePrefix("ff00::/8"),
}

// isPublic reports whether a is a public address. An IPv4 address written as IPv6 is judged as the IPv4 address it holds.
func isPublic(a netip.Addr) bool {
	if !a.IsValid() {
		return false
	}
	a = a.Unmap()
	return !slices.ContainsFunc(nonPublic, func(p netip.Prefix) bool { return p.Contains(a) })
}

// hostAddrs returns the addresses host stands for: host itself when it is an IP address, else every address the Resolver
// finds for it. An address that cannot be read is returned as the zero netip.Addr, which isPublic refuses.
func (s *Service) hostAddrs(ctx context.Context, host string) ([]netip.Addr, error) {
	if a, err := netip.ParseAddr(host); err == nil {
		return []netip.Addr{a}, nil
	}
	ips, err := s.resolver.LookupIPAddr(ctx, host)
	if err != nil {
		return nil, err
	}
	addrs := make([]netip.Addr, 0, len(ips))
	for _, ip := range ips {
		a, _ := netip.AddrFromSlice(ip.IP)
		addrs = append(addrs, a)
	}
	return addrs, nil
}

// CheckURL checks a webhook URL before it is saved: an absolute https URL with a host and no user name or password, whose
// host resolves only to public addresses.
func (s *Service) CheckURL(ctx context.Context, raw string) error {
	u, err := url.Parse(raw)
	if err != nil || u.Scheme != "https" || u.Host == "" || u.Hostname() == "" || u.User != nil {
		return fmt.Errorf("%w: use an absolute https URL with a host and no user name or password", ErrInvalidURL)
	}
	host := u.Hostname()
	addrs, err := s.hostAddrs(ctx, host)
	if err != nil || len(addrs) == 0 {
		return fmt.Errorf("%w: the host %q does not resolve", ErrInvalidURL, host)
	}
	for _, a := range addrs {
		if !isPublic(a) {
			return fmt.Errorf("%w: the host %q is not a public address", ErrInvalidURL, host)
		}
	}
	return nil
}

